window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2d9ec7a49c4ee5b6"]={"versions": [{"id": "FIG-2d9ec7a49c4ee5b6", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm zur Darstellung einer AUTOSAR BSW-Modul-Konfigurationsbeschreibung (ECUC-Metamodell-Definition nach AUTOSAR Generic Structure Template / Parameter Definition).</li>\n<li><strong>Architektur-Kontext:</strong> Konfigurationsmodell des Classic Platform Betriebssystems (<code>AUTOSAR_SWS_OS</code>, R21-11, Container <code>ECUC_Os_00006</code>). Definiert das statische Daten- und Beziehungsmodell für <code>OsAlarm</code>-Instanzen, deren Bindung an Basis-Zähler (<code>OsCounter</code>), Autostart-Verhalten über <code>OsAppMode</code>, Partitionszugehörigkeiten (<code>OsApplication</code>) sowie die auszuführende Benachrichtigungsaktion (<code>OsAlarmAction</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### 2.1 Wurzelcontainer</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarm</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..*]</code>): Zentraler Konfigurationscontainer für OS-Alarme.</li>\n<li><strong><code>OsAlarmCounterRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..1]</code>): Obligatorische Referenz auf den zugrundeliegenden Basiszähler (<code>+destination OsCounter</code>).</li>\n<li><strong><code>OsAlarmAccessingApplication</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[0..*]</code>): Referenzen auf <code>OsApplication</code>-Instanzen (<code>+destination OsApplication</code>), die Berechtigung für API-Zugriffe (z. B. <code>SetRelAlarm</code>, <code>CancelAlarm</code>, <code>GetAlarm</code>) besitzen.</li>\n</ul>\n<p class=\"fig-p\">#### 2.2 Autostart-Konfiguration (<code>OsAlarmAutostart</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAutostart</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..1]</code>, <code>+subContainer</code>):</li>\n<li><strong><code>OsAlarmAlarmTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Start-Ablaufzeitpunkt bzw. initialer Offset in Counter-Ticks.</li>\n<li><strong><code>OsAlarmCycleTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Zykluszeit für periodische Alarme (<code>0</code> = Einmalalarm).</li>\n<li><strong><code>OsAlarmAutostartType</code></strong> (<code>EcucEnumerationParamDef</code>): Art des initialen Verfalls; Literale:</li>\n<li><code>ABSOLUTE</code>: Alarm läuft ab, wenn der Counter exakt <code>OsAlarmAlarmTime</code> erreicht.</li>\n<li><code>RELATIVE</code>: Alarm läuft ab <code>OsAlarmAlarmTime</code> Ticks nach <code>StartOS()</code>.</li>\n<li><strong><code>OsAlarmAppModeRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..*]</code>, <code>+destination OsAppMode</code>): Bindet den Autostart an mindestens einen spezifischen Applikationsmodus.</li>\n</ul>\n<p class=\"fig-p\">#### 2.3 Exklusive Aktionsdefinition (<code>OsAlarmAction</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAction</code></strong> (<code>EcucChoiceContainerDef</code>, Multiplizität <code>[1..1]</code>, <code>+subContainer</code>): Choice-Container; verlangt exakt eine der folgenden Spezialisierungen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmActivateTask</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmActivateTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den zu aktivierenden Task (<code>+destination OsTask</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmSetEvent</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmSetEventTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den Ziel-Extended-Task (<code>+destination OsTask</code>).</li>\n<li><code>OsAlarmSetEventRef</code> (<code>EcucReferenceDef</code>): Referenz auf das zu setzende Event (<code>+destination OsEvent</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmCallback</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmCallbackName</code> (<code>EcucFunctionNameDef</code>): Name der auszuführenden C-Callback-Funktion (<code>ALARMCALLBACK(Function)</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmIncrementCounter</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmIncrementCounterRef</code> (<code>EcucReferenceDef</code>): Referenz auf einen sekundären Zähler (<code>+destination OsCounter</code>), der bei Ablauf inkrementiert wird (Zählerkaskadierung).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[StartOS(AppMode)]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Ist AppMode in OsAlarmAppModeRef?</p>\n<p class=\"fig-p\">├── JA ──► Initialisiere Alarm (ABSOLUTE / RELATIVE mit AlarmTime, CycleTime)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm verbleibt inaktiv (Aktivierung zur Laufzeit via SetRelAlarm / SetAbsAlarm)</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">[Counter Tick / IncrementCounter]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Counter-Stand == Verfallszeitpunkt?</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├── NEIN ─► Weiterer Zählerbetrieb</p>\n<p class=\"fig-p\">└── JA ───► Triggere deterministische OsAlarmAction (Synchron im ISR- bzw. Counter-Kontext):</p>\n<p class=\"fig-p\">├── ActivateTask:       ActivateTask(TaskID)</p>\n<p class=\"fig-p\">├── SetEvent:           SetEvent(TaskID, EventMask)</p>\n<p class=\"fig-p\">├── Callback:           Aufruf von OsAlarmCallbackName()</p>\n<p class=\"fig-p\">└── IncrementCounter:   Inkrementiere Ziel-Counter</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">OsAlarmCycleTime > 0?</p>\n<p class=\"fig-p\">├── JA ──► Berechne nächsten Verfallspunkt (Alarm bleibt scharf)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm geht in Status 'CANCELLED/STOPPED'</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Trigger:</strong> Expiration tritt ein, wenn der referenzierte Basiszähler den Zielwert erreicht.</li>\n<li><strong>Synchronizität:</strong> Die konfigurierte Aktion wird synchron innerhalb des Kontexts ausgeführt, der den zugrundeliegenden Zähler fortschreibt (z. B. Timer-ISR bei HW-Countern oder Task-Kontext bei SW-Countern via <code>IncrementCounter()</code>).</li>\n<li><strong>Reload-Verhalten:</strong> Bei <code>OsAlarmCycleTime &gt; 0</code> erfolgt das automatische Nachladen ohne Interaktion des Anwendungs-Codes.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Code-Generierung (Generator-Vertrag):</strong></li>\n<li>Der BSW-OS-Generator übersetzt die Strukturen direkt in ROM-Konstantentabellen (<code>AlarmAutostartType</code>, <code>AlarmType</code>, Deskriptoren) und Funktionszeiger-Arrays.</li>\n<li>Fehlkonfigurationen (z. B. mehrere Choices unter <code>OsAlarmAction</code> oder fehlende <code>OsAlarmCounterRef</code>) müssen vom Generator zur Validierungszeit (Pre-Compile) abgefangen werden.</li>\n<li><strong>Restriktionen & Skalierbarkeitsklassen:</strong></li>\n<li><strong><code>OsAlarmCallback</code>:</strong> In sicherheitskritischen Systemen bzw. höheren Scalability Classes (SC3/SC4 mit Memory-Protection / Timing-Protection) ist die Verwendung von Callbacks oft restriktiert oder verboten, da sie im Interrupt-Kontext laufen und Stack-Overhead sowie Schutzbereichsverletzungen begünstigen. Bevorzugt sind <code>OsAlarmActivateTask</code> oder <code>OsAlarmSetEvent</code>.</li>\n<li><strong>Extended vs. Basic Tasks:</strong> <code>OsAlarmSetEvent</code> darf normativ nur auf Tasks referenzieren, die als Extended Tasks konfiguriert sind (Besitz mindestens eines <code>OsEvent</code>).</li>\n<li><strong>Multi-Core & Partitioning (Memory Protection):</strong></li>\n<li><code>OsAlarmAccessingApplication</code> bestimmt die Berechtigungsmatrix in OS-Applications (<code>Trusted</code> vs. <code>Non-Trusted</code>). Fehlt einer aufrufenden Partition die Referenz in <code>OsAlarmAccessingApplication</code>, retournieren die APIs <code>SetRelAlarm()</code>, <code>SetAbsAlarm()</code> und <code>CancelAlarm()</code> den Statuscode <code>E_OS_ACCESS</code>.</li>\n<li>Alarme laufen zwingend auf dem Core, dem der referenzierte Basiszähler (<code>OsAlarmCounterRef</code>) zugewiesen ist. Cross-Core-Alarmaktionen erfordern Core-übergreifende Inter-OS-Kommunikation (IOC) oder Rescheduling durch den OS-Kernel.</li>\n</ul>"}, {"id": "FIG-2a26d9c0e1cd7af6", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm zur Darstellung einer AUTOSAR BSW-Modul-Konfigurationsbeschreibung (ECUC-Metamodell-Definition nach AUTOSAR Generic Structure Template / Parameter Definition).</li>\n<li><strong>Architektur-Kontext:</strong> Konfigurationsmodell des Classic Platform Betriebssystems (<code>AUTOSAR_SWS_OS</code>, R21-11, Container <code>ECUC_Os_00006</code>). Definiert das statische Daten- und Beziehungsmodell für <code>OsAlarm</code>-Instanzen, deren Bindung an Basis-Zähler (<code>OsCounter</code>), Autostart-Verhalten über <code>OsAppMode</code>, Partitionszugehörigkeiten (<code>OsApplication</code>) sowie die auszuführende Benachrichtigungsaktion (<code>OsAlarmAction</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### 2.1 Wurzelcontainer</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarm</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..*]</code>): Zentraler Konfigurationscontainer für OS-Alarme.</li>\n<li><strong><code>OsAlarmCounterRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..1]</code>): Obligatorische Referenz auf den zugrundeliegenden Basiszähler (<code>+destination OsCounter</code>).</li>\n<li><strong><code>OsAlarmAccessingApplication</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[0..*]</code>): Referenzen auf <code>OsApplication</code>-Instanzen (<code>+destination OsApplication</code>), die Berechtigung für API-Zugriffe (z. B. <code>SetRelAlarm</code>, <code>CancelAlarm</code>, <code>GetAlarm</code>) besitzen.</li>\n</ul>\n<p class=\"fig-p\">#### 2.2 Autostart-Konfiguration (<code>OsAlarmAutostart</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAutostart</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..1]</code>, <code>+subContainer</code>):</li>\n<li><strong><code>OsAlarmAlarmTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Start-Ablaufzeitpunkt bzw. initialer Offset in Counter-Ticks.</li>\n<li><strong><code>OsAlarmCycleTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Zykluszeit für periodische Alarme (<code>0</code> = Einmalalarm).</li>\n<li><strong><code>OsAlarmAutostartType</code></strong> (<code>EcucEnumerationParamDef</code>): Art des initialen Verfalls; Literale:</li>\n<li><code>ABSOLUTE</code>: Alarm läuft ab, wenn der Counter exakt <code>OsAlarmAlarmTime</code> erreicht.</li>\n<li><code>RELATIVE</code>: Alarm läuft ab <code>OsAlarmAlarmTime</code> Ticks nach <code>StartOS()</code>.</li>\n<li><strong><code>OsAlarmAppModeRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..*]</code>, <code>+destination OsAppMode</code>): Bindet den Autostart an mindestens einen spezifischen Applikationsmodus.</li>\n</ul>\n<p class=\"fig-p\">#### 2.3 Exklusive Aktionsdefinition (<code>OsAlarmAction</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAction</code></strong> (<code>EcucChoiceContainerDef</code>, Multiplizität <code>[1..1]</code>, <code>+subContainer</code>): Choice-Container; verlangt exakt eine der folgenden Spezialisierungen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmActivateTask</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmActivateTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den zu aktivierenden Task (<code>+destination OsTask</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmSetEvent</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmSetEventTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den Ziel-Extended-Task (<code>+destination OsTask</code>).</li>\n<li><code>OsAlarmSetEventRef</code> (<code>EcucReferenceDef</code>): Referenz auf das zu setzende Event (<code>+destination OsEvent</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmCallback</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmCallbackName</code> (<code>EcucFunctionNameDef</code>): Name der auszuführenden C-Callback-Funktion (<code>ALARMCALLBACK(Function)</code>).</li>\n<li><code>OsMemoryMappingCodeLocationRef</code> (<code>EcucForeignReferenceDef</code>, Multiplizität <code>[0..1]</code>): Optionale Fremdreferenz mit Zieltyp <code>SW-ADDR-METHOD</code> zur Zuordnung des Callback-Codes zu einem spezifischen Speicherabschnitt (AUTOSAR Memory Mapping).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmIncrementCounter</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmIncrementCounterRef</code> (<code>EcucReferenceDef</code>): Referenz auf einen sekundären Zähler (<code>+destination OsCounter</code>), der bei Ablauf inkrementiert wird (Zählerkaskadierung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[StartOS(AppMode)]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Ist AppMode in OsAlarmAppModeRef?</p>\n<p class=\"fig-p\">├── JA ──► Initialisiere Alarm (ABSOLUTE / RELATIVE mit AlarmTime, CycleTime)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm verbleibt inaktiv (Aktivierung zur Laufzeit via SetRelAlarm / SetAbsAlarm)</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">[Counter Tick / IncrementCounter]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Counter-Stand == Verfallszeitpunkt?</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├── NEIN ─► Weiterer Zählerbetrieb</p>\n<p class=\"fig-p\">└── JA ───► Triggere deterministische OsAlarmAction (Synchron im ISR- bzw. Counter-Kontext):</p>\n<p class=\"fig-p\">├── ActivateTask:       ActivateTask(TaskID)</p>\n<p class=\"fig-p\">├── SetEvent:           SetEvent(TaskID, EventMask)</p>\n<p class=\"fig-p\">├── Callback:           Aufruf von OsAlarmCallbackName()</p>\n<p class=\"fig-p\">└── IncrementCounter:   Inkrementiere Ziel-Counter</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">OsAlarmCycleTime > 0?</p>\n<p class=\"fig-p\">├── JA ──► Berechne nächsten Verfallspunkt (Alarm bleibt scharf)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm geht in Status 'CANCELLED/STOPPED'</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Trigger:</strong> Expiration tritt ein, wenn der referenzierte Basiszähler den Zielwert erreicht.</li>\n<li><strong>Synchronizität:</strong> Die konfigurierte Aktion wird synchron innerhalb des Kontexts ausgeführt, der den zugrundeliegenden Zähler fortschreibt (z. B. Timer-ISR bei HW-Countern oder Task-Kontext bei SW-Countern via <code>IncrementCounter()</code>).</li>\n<li><strong>Reload-Verhalten:</strong> Bei <code>OsAlarmCycleTime &gt; 0</code> erfolgt das automatische Nachladen ohne Interaktion des Anwendungs-Codes.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Code-Generierung (Generator-Vertrag):</strong></li>\n<li>Der BSW-OS-Generator übersetzt die Strukturen direkt in ROM-Konstantentabellen (<code>AlarmAutostartType</code>, <code>AlarmType</code>, Deskriptoren) und Funktionszeiger-Arrays.</li>\n<li>Fehlkonfigurationen (z. B. mehrere Choices unter <code>OsAlarmAction</code> oder fehlende <code>OsAlarmCounterRef</code>) müssen vom Generator zur Validierungszeit (Pre-Compile) abgefangen werden.</li>\n<li><strong>Restriktionen & Skalierbarkeitsklassen:</strong></li>\n<li><strong><code>OsAlarmCallback</code>:</strong> In sicherheitskritischen Systemen bzw. höheren Scalability Classes (SC3/SC4 mit Memory-Protection / Timing-Protection) ist die Verwendung von Callbacks oft restriktiert oder verboten, da sie im Interrupt-Kontext laufen und Stack-Overhead sowie Schutzbereichsverletzungen begünstigen. Bevorzugt sind <code>OsAlarmActivateTask</code> oder <code>OsAlarmSetEvent</code>.</li>\n<li><strong>Extended vs. Basic Tasks:</strong> <code>OsAlarmSetEvent</code> darf normativ nur auf Tasks referenzieren, die als Extended Tasks konfiguriert sind (Besitz mindestens eines <code>OsEvent</code>).</li>\n<li><strong>Multi-Core & Partitioning (Memory Protection):</strong></li>\n<li><code>OsAlarmAccessingApplication</code> bestimmt die Berechtigungsmatrix in OS-Applications (<code>Trusted</code> vs. <code>Non-Trusted</code>). Fehlt einer aufrufenden Partition die Referenz in <code>OsAlarmAccessingApplication</code>, retournieren die APIs <code>SetRelAlarm()</code>, <code>SetAbsAlarm()</code> und <code>CancelAlarm()</code> den Statuscode <code>E_OS_ACCESS</code>.</li>\n<li>Alarme laufen zwingend auf dem Core, dem der referenzierte Basiszähler (<code>OsAlarmCounterRef</code>) zugewiesen ist. Cross-Core-Alarmaktionen erfordern Core-übergreifende Inter-OS-Kommunikation (IOC) oder Rescheduling durch den OS-Kernel.</li>\n</ul>"}, {"id": "FIG-2791e9a190bcaa26", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm zur Darstellung einer AUTOSAR BSW-Modul-Konfigurationsbeschreibung (ECUC-Metamodell-Definition nach AUTOSAR Generic Structure Template / Parameter Definition).</li>\n<li><strong>Architektur-Kontext:</strong> Konfigurationsmodell des Classic Platform Betriebssystems (<code>AUTOSAR_SWS_OS</code>, R21-11, Container <code>ECUC_Os_00006</code>). Definiert das statische Daten- und Beziehungsmodell für <code>OsAlarm</code>-Instanzen, deren Bindung an Basis-Zähler (<code>OsCounter</code>), Autostart-Verhalten über <code>OsAppMode</code>, Partitionszugehörigkeiten (<code>OsApplication</code>) sowie die auszuführende Benachrichtigungsaktion (<code>OsAlarmAction</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### 2.1 Wurzelcontainer</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarm</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..*]</code>): Zentraler Konfigurationscontainer für OS-Alarme.</li>\n<li><strong><code>OsAlarmCounterRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..1]</code>): Obligatorische Referenz auf den zugrundeliegenden Basiszähler (<code>+destination OsCounter</code>).</li>\n<li><strong><code>OsAlarmAccessingApplication</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[0..*]</code>): Referenzen auf <code>OsApplication</code>-Instanzen (<code>+destination OsApplication</code>), die Berechtigung für API-Zugriffe (z. B. <code>SetRelAlarm</code>, <code>CancelAlarm</code>, <code>GetAlarm</code>) besitzen.</li>\n</ul>\n<p class=\"fig-p\">#### 2.2 Autostart-Konfiguration (<code>OsAlarmAutostart</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAutostart</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..1]</code>, <code>+subContainer</code>):</li>\n<li><strong><code>OsAlarmAlarmTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Start-Ablaufzeitpunkt bzw. initialer Offset in Counter-Ticks.</li>\n<li><strong><code>OsAlarmCycleTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Zykluszeit für periodische Alarme (<code>0</code> = Einmalalarm).</li>\n<li><strong><code>OsAlarmAutostartType</code></strong> (<code>EcucEnumerationParamDef</code>): Art des initialen Verfalls; Literale:</li>\n<li><code>ABSOLUTE</code>: Alarm läuft ab, wenn der Counter exakt <code>OsAlarmAlarmTime</code> erreicht.</li>\n<li><code>RELATIVE</code>: Alarm läuft ab <code>OsAlarmAlarmTime</code> Ticks nach <code>StartOS()</code>.</li>\n<li><strong><code>OsAlarmAppModeRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..*]</code>, <code>+destination OsAppMode</code>): Bindet den Autostart an mindestens einen spezifischen Applikationsmodus.</li>\n</ul>\n<p class=\"fig-p\">#### 2.3 Exklusive Aktionsdefinition (<code>OsAlarmAction</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAction</code></strong> (<code>EcucChoiceContainerDef</code>, Multiplizität <code>[1..1]</code>, <code>+subContainer</code>): Choice-Container; verlangt exakt eine der folgenden Spezialisierungen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmActivateTask</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmActivateTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den zu aktivierenden Task (<code>+destination OsTask</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmSetEvent</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmSetEventTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den Ziel-Extended-Task (<code>+destination OsTask</code>).</li>\n<li><code>OsAlarmSetEventRef</code> (<code>EcucReferenceDef</code>): Referenz auf das zu setzende Event (<code>+destination OsEvent</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmCallback</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmCallbackName</code> (<code>EcucFunctionNameDef</code>): Name der auszuführenden C-Callback-Funktion (<code>ALARMCALLBACK(Function)</code>).</li>\n<li><code>OsMemoryMappingCodeLocationRef</code> (<code>EcucForeignReferenceDef</code>, Multiplizität <code>[0..1]</code>): Optionale Fremdreferenz mit Zieltyp <code>SW-ADDR-METHOD</code> zur Zuordnung des Callback-Codes zu einem spezifischen Speicherabschnitt (AUTOSAR Memory Mapping).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmIncrementCounter</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmIncrementCounterRef</code> (<code>EcucReferenceDef</code>): Referenz auf einen sekundären Zähler (<code>+destination OsCounter</code>), der bei Ablauf inkrementiert wird (Zählerkaskadierung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[StartOS(AppMode)]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Ist AppMode in OsAlarmAppModeRef?</p>\n<p class=\"fig-p\">├── JA ──► Initialisiere Alarm (ABSOLUTE / RELATIVE mit AlarmTime, CycleTime)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm verbleibt inaktiv (Aktivierung zur Laufzeit via SetRelAlarm / SetAbsAlarm)</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">[Counter Tick / IncrementCounter]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Counter-Stand == Verfallszeitpunkt?</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├── NEIN ─► Weiterer Zählerbetrieb</p>\n<p class=\"fig-p\">└── JA ───► Triggere deterministische OsAlarmAction (Synchron im ISR- bzw. Counter-Kontext):</p>\n<p class=\"fig-p\">├── ActivateTask:       ActivateTask(TaskID)</p>\n<p class=\"fig-p\">├── SetEvent:           SetEvent(TaskID, EventMask)</p>\n<p class=\"fig-p\">├── Callback:           Aufruf von OsAlarmCallbackName()</p>\n<p class=\"fig-p\">└── IncrementCounter:   Inkrementiere Ziel-Counter</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">OsAlarmCycleTime > 0?</p>\n<p class=\"fig-p\">├── JA ──► Berechne nächsten Verfallspunkt (Alarm bleibt scharf)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm geht in Status 'CANCELLED/STOPPED'</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Trigger:</strong> Expiration tritt ein, wenn der referenzierte Basiszähler den Zielwert erreicht.</li>\n<li><strong>Synchronizität:</strong> Die konfigurierte Aktion wird synchron innerhalb des Kontexts ausgeführt, der den zugrundeliegenden Zähler fortschreibt (z. B. Timer-ISR bei HW-Countern oder Task-Kontext bei SW-Countern via <code>IncrementCounter()</code>).</li>\n<li><strong>Reload-Verhalten:</strong> Bei <code>OsAlarmCycleTime &gt; 0</code> erfolgt das automatische Nachladen ohne Interaktion des Anwendungs-Codes.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Code-Generierung (Generator-Vertrag):</strong></li>\n<li>Der BSW-OS-Generator übersetzt die Strukturen direkt in ROM-Konstantentabellen (<code>AlarmAutostartType</code>, <code>AlarmType</code>, Deskriptoren) und Funktionszeiger-Arrays.</li>\n<li>Fehlkonfigurationen (z. B. mehrere Choices unter <code>OsAlarmAction</code> oder fehlende <code>OsAlarmCounterRef</code>) müssen vom Generator zur Validierungszeit (Pre-Compile) abgefangen werden.</li>\n<li><strong>Restriktionen & Skalierbarkeitsklassen:</strong></li>\n<li><strong><code>OsAlarmCallback</code>:</strong> In sicherheitskritischen Systemen bzw. höheren Scalability Classes (SC3/SC4 mit Memory-Protection / Timing-Protection) ist die Verwendung von Callbacks oft restriktiert oder verboten, da sie im Interrupt-Kontext laufen und Stack-Overhead sowie Schutzbereichsverletzungen begünstigen. Bevorzugt sind <code>OsAlarmActivateTask</code> oder <code>OsAlarmSetEvent</code>.</li>\n<li><strong>Extended vs. Basic Tasks:</strong> <code>OsAlarmSetEvent</code> darf normativ nur auf Tasks referenzieren, die als Extended Tasks konfiguriert sind (Besitz mindestens eines <code>OsEvent</code>).</li>\n<li><strong>Multi-Core & Partitioning (Memory Protection):</strong></li>\n<li><code>OsAlarmAccessingApplication</code> bestimmt die Berechtigungsmatrix in OS-Applications (<code>Trusted</code> vs. <code>Non-Trusted</code>). Fehlt einer aufrufenden Partition die Referenz in <code>OsAlarmAccessingApplication</code>, retournieren die APIs <code>SetRelAlarm()</code>, <code>SetAbsAlarm()</code> und <code>CancelAlarm()</code> den Statuscode <code>E_OS_ACCESS</code>.</li>\n<li>Alarme laufen zwingend auf dem Core, dem der referenzierte Basiszähler (<code>OsAlarmCounterRef</code>) zugewiesen ist. Cross-Core-Alarmaktionen erfordern Core-übergreifende Inter-OS-Kommunikation (IOC) oder Rescheduling durch den OS-Kernel.</li>\n</ul>"}, {"id": "FIG-4da60f542df9ab87", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm zur Darstellung einer AUTOSAR BSW-Modul-Konfigurationsbeschreibung (ECUC-Metamodell-Definition nach AUTOSAR Generic Structure Template / Parameter Definition).</li>\n<li><strong>Architektur-Kontext:</strong> Konfigurationsmodell des Classic Platform Betriebssystems (<code>AUTOSAR_SWS_OS</code>, R21-11, Container <code>ECUC_Os_00006</code>). Definiert das statische Daten- und Beziehungsmodell für <code>OsAlarm</code>-Instanzen, deren Bindung an Basis-Zähler (<code>OsCounter</code>), Autostart-Verhalten über <code>OsAppMode</code>, Partitionszugehörigkeiten (<code>OsApplication</code>) sowie die auszuführende Benachrichtigungsaktion (<code>OsAlarmAction</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### 2.1 Wurzelcontainer</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarm</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..*]</code>): Zentraler Konfigurationscontainer für OS-Alarme.</li>\n<li><strong><code>OsAlarmCounterRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..1]</code>): Obligatorische Referenz auf den zugrundeliegenden Basiszähler (<code>+destination OsCounter</code>).</li>\n<li><strong><code>OsAlarmAccessingApplication</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[0..*]</code>): Referenzen auf <code>OsApplication</code>-Instanzen (<code>+destination OsApplication</code>), die Berechtigung für API-Zugriffe (z. B. <code>SetRelAlarm</code>, <code>CancelAlarm</code>, <code>GetAlarm</code>) besitzen.</li>\n</ul>\n<p class=\"fig-p\">#### 2.2 Autostart-Konfiguration (<code>OsAlarmAutostart</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAutostart</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..1]</code>, <code>+subContainer</code>):</li>\n<li><strong><code>OsAlarmAlarmTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Start-Ablaufzeitpunkt bzw. initialer Offset in Counter-Ticks.</li>\n<li><strong><code>OsAlarmCycleTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Zykluszeit für periodische Alarme (<code>0</code> = Einmalalarm).</li>\n<li><strong><code>OsAlarmAutostartType</code></strong> (<code>EcucEnumerationParamDef</code>): Art des initialen Verfalls; Literale:</li>\n<li><code>ABSOLUTE</code>: Alarm läuft ab, wenn der Counter exakt <code>OsAlarmAlarmTime</code> erreicht.</li>\n<li><code>RELATIVE</code>: Alarm läuft ab <code>OsAlarmAlarmTime</code> Ticks nach <code>StartOS()</code>.</li>\n<li><strong><code>OsAlarmAppModeRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..*]</code>, <code>+destination OsAppMode</code>): Bindet den Autostart an mindestens einen spezifischen Applikationsmodus.</li>\n</ul>\n<p class=\"fig-p\">#### 2.3 Exklusive Aktionsdefinition (<code>OsAlarmAction</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAction</code></strong> (<code>EcucChoiceContainerDef</code>, Multiplizität <code>[1..1]</code>, <code>+subContainer</code>): Choice-Container; verlangt exakt eine der folgenden Spezialisierungen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmActivateTask</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmActivateTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den zu aktivierenden Task (<code>+destination OsTask</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmSetEvent</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmSetEventTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den Ziel-Extended-Task (<code>+destination OsTask</code>).</li>\n<li><code>OsAlarmSetEventRef</code> (<code>EcucReferenceDef</code>): Referenz auf das zu setzende Event (<code>+destination OsEvent</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmCallback</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmCallbackName</code> (<code>EcucFunctionNameDef</code>): Name der auszuführenden C-Callback-Funktion (<code>ALARMCALLBACK(Function)</code>).</li>\n<li><code>OsMemoryMappingCodeLocationRef</code> (<code>EcucForeignReferenceDef</code>, Multiplizität <code>[0..1]</code>): Optionale Fremdreferenz mit Zieltyp <code>SW-ADDR-METHOD</code> zur Zuordnung des Callback-Codes zu einem spezifischen Speicherabschnitt (AUTOSAR Memory Mapping).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmIncrementCounter</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmIncrementCounterRef</code> (<code>EcucReferenceDef</code>): Referenz auf einen sekundären Zähler (<code>+destination OsCounter</code>), der bei Ablauf inkrementiert wird (Zählerkaskadierung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[StartOS(AppMode)]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Ist AppMode in OsAlarmAppModeRef?</p>\n<p class=\"fig-p\">├── JA ──► Initialisiere Alarm (ABSOLUTE / RELATIVE mit AlarmTime, CycleTime)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm verbleibt inaktiv (Aktivierung zur Laufzeit via SetRelAlarm / SetAbsAlarm)</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">[Counter Tick / IncrementCounter]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Counter-Stand == Verfallszeitpunkt?</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├── NEIN ─► Weiterer Zählerbetrieb</p>\n<p class=\"fig-p\">└── JA ───► Triggere deterministische OsAlarmAction (Synchron im ISR- bzw. Counter-Kontext):</p>\n<p class=\"fig-p\">├── ActivateTask:       ActivateTask(TaskID)</p>\n<p class=\"fig-p\">├── SetEvent:           SetEvent(TaskID, EventMask)</p>\n<p class=\"fig-p\">├── Callback:           Aufruf von OsAlarmCallbackName()</p>\n<p class=\"fig-p\">└── IncrementCounter:   Inkrementiere Ziel-Counter</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">OsAlarmCycleTime > 0?</p>\n<p class=\"fig-p\">├── JA ──► Berechne nächsten Verfallspunkt (Alarm bleibt scharf)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm geht in Status 'CANCELLED/STOPPED'</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Trigger:</strong> Expiration tritt ein, wenn der referenzierte Basiszähler den Zielwert erreicht.</li>\n<li><strong>Synchronizität:</strong> Die konfigurierte Aktion wird synchron innerhalb des Kontexts ausgeführt, der den zugrundeliegenden Zähler fortschreibt (z. B. Timer-ISR bei HW-Countern oder Task-Kontext bei SW-Countern via <code>IncrementCounter()</code>).</li>\n<li><strong>Reload-Verhalten:</strong> Bei <code>OsAlarmCycleTime &gt; 0</code> erfolgt das automatische Nachladen ohne Interaktion des Anwendungs-Codes.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Code-Generierung (Generator-Vertrag):</strong></li>\n<li>Der BSW-OS-Generator übersetzt die Strukturen direkt in ROM-Konstantentabellen (<code>AlarmAutostartType</code>, <code>AlarmType</code>, Deskriptoren) und Funktionszeiger-Arrays.</li>\n<li>Fehlkonfigurationen (z. B. mehrere Choices unter <code>OsAlarmAction</code> oder fehlende <code>OsAlarmCounterRef</code>) müssen vom Generator zur Validierungszeit (Pre-Compile) abgefangen werden.</li>\n<li><strong>Restriktionen & Skalierbarkeitsklassen:</strong></li>\n<li><strong><code>OsAlarmCallback</code>:</strong> In sicherheitskritischen Systemen bzw. höheren Scalability Classes (SC3/SC4 mit Memory-Protection / Timing-Protection) ist die Verwendung von Callbacks oft restriktiert oder verboten, da sie im Interrupt-Kontext laufen und Stack-Overhead sowie Schutzbereichsverletzungen begünstigen. Bevorzugt sind <code>OsAlarmActivateTask</code> oder <code>OsAlarmSetEvent</code>.</li>\n<li><strong>Extended vs. Basic Tasks:</strong> <code>OsAlarmSetEvent</code> darf normativ nur auf Tasks referenzieren, die als Extended Tasks konfiguriert sind (Besitz mindestens eines <code>OsEvent</code>).</li>\n<li><strong>Multi-Core & Partitioning (Memory Protection):</strong></li>\n<li><code>OsAlarmAccessingApplication</code> bestimmt die Berechtigungsmatrix in OS-Applications (<code>Trusted</code> vs. <code>Non-Trusted</code>). Fehlt einer aufrufenden Partition die Referenz in <code>OsAlarmAccessingApplication</code>, retournieren die APIs <code>SetRelAlarm()</code>, <code>SetAbsAlarm()</code> und <code>CancelAlarm()</code> den Statuscode <code>E_OS_ACCESS</code>.</li>\n<li>Alarme laufen zwingend auf dem Core, dem der referenzierte Basiszähler (<code>OsAlarmCounterRef</code>) zugewiesen ist. Cross-Core-Alarmaktionen erfordern Core-übergreifende Inter-OS-Kommunikation (IOC) oder Rescheduling durch den OS-Kernel.</li>\n</ul>"}, {"id": "FIG-d17ad99c3d408f84", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm zur Darstellung einer AUTOSAR BSW-Modul-Konfigurationsbeschreibung (ECUC-Metamodell-Definition nach AUTOSAR Generic Structure Template / Parameter Definition).</li>\n<li><strong>Architektur-Kontext:</strong> Konfigurationsmodell des Classic Platform Betriebssystems (<code>AUTOSAR_SWS_OS</code>, R21-11, Container <code>ECUC_Os_00006</code>). Definiert das statische Daten- und Beziehungsmodell für <code>OsAlarm</code>-Instanzen, deren Bindung an Basis-Zähler (<code>OsCounter</code>), Autostart-Verhalten über <code>OsAppMode</code>, Partitionszugehörigkeiten (<code>OsApplication</code>) sowie die auszuführende Benachrichtigungsaktion (<code>OsAlarmAction</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### 2.1 Wurzelcontainer</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarm</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..*]</code>): Zentraler Konfigurationscontainer für OS-Alarme.</li>\n<li><strong><code>OsAlarmCounterRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..1]</code>): Obligatorische Referenz auf den zugrundeliegenden Basiszähler (<code>+destination OsCounter</code>).</li>\n<li><strong><code>OsAlarmAccessingApplication</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[0..*]</code>): Referenzen auf <code>OsApplication</code>-Instanzen (<code>+destination OsApplication</code>), die Berechtigung für API-Zugriffe (z. B. <code>SetRelAlarm</code>, <code>CancelAlarm</code>, <code>GetAlarm</code>) besitzen.</li>\n</ul>\n<p class=\"fig-p\">#### 2.2 Autostart-Konfiguration (<code>OsAlarmAutostart</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAutostart</code></strong> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..1]</code>, <code>+subContainer</code>):</li>\n<li><strong><code>OsAlarmAppModeRef</code></strong> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..*]</code>, <code>+destination OsAppMode</code>): Bindet den Autostart an mindestens einen spezifischen Applikationsmodus.</li>\n<li><strong><code>OsAlarmAlarmTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Start-Ablaufzeitpunkt bzw. initialer Offset in Counter-Ticks.</li>\n<li><strong><code>OsAlarmCycleTime</code></strong> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>): Zykluszeit für periodische Alarme (<code>0</code> = Einmalalarm).</li>\n<li><strong><code>OsAlarmAutostartType</code></strong> (<code>EcucEnumerationParamDef</code>): Art des initialen Verfalls; Literale:</li>\n<li><code>ABSOLUTE</code>: Alarm läuft ab, wenn der Counter exakt <code>OsAlarmAlarmTime</code> erreicht.</li>\n<li><code>RELATIVE</code>: Alarm läuft ab <code>OsAlarmAlarmTime</code> Ticks nach <code>StartOS()</code>.</li>\n</ul>\n<p class=\"fig-p\">#### 2.3 Exklusive Aktionsdefinition (<code>OsAlarmAction</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>OsAlarmAction</code></strong> (<code>EcucChoiceContainerDef</code>, Multiplizität <code>[1..1]</code>, <code>+subContainer</code>): Choice-Container; verlangt exakt eine der folgenden Spezialisierungen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmIncrementCounter</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmIncrementCounterRef</code> (<code>EcucReferenceDef</code>): Referenz auf einen sekundären Zähler (<code>+destination OsCounter</code>), der bei Ablauf inkrementiert wird (Zählerkaskadierung).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmActivateTask</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmActivateTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den zu aktivierenden Task (<code>+destination OsTask</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmSetEvent</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmSetEventTaskRef</code> (<code>EcucReferenceDef</code>): Referenz auf den Ziel-Extended-Task (<code>+destination OsTask</code>).</li>\n<li><code>OsAlarmSetEventRef</code> (<code>EcucReferenceDef</code>): Referenz auf das zu setzende Event (<code>+destination OsEvent</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmCallback</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmCallbackName</code> (<code>EcucFunctionNameDef</code>): Name der auszuführenden C-Callback-Funktion (<code>ALARMCALLBACK(Function)</code>).</li>\n<li><code>OsMemoryMappingCodeLocationRef</code> (<code>EcucForeignReferenceDef</code>, Multiplizität <code>[0..1]</code>): Optionale Fremdreferenz mit Zieltyp <code>SW-ADDR-METHOD</code> zur Zuordnung des Callback-Codes zu einem spezifischen Speicherabschnitt (AUTOSAR Memory Mapping).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>OsAlarmBudgetReplenish</code></strong> (<code>EcucParamConfContainerDef</code>, <code>[0..1]</code>):</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>OsAlarmBudgetReplenishRef</code> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..1]</code>): Obligatorische Referenz auf die zugehörige Budget-Replenishment-Konfiguration (Timing Protection / Execution Budget).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">[StartOS(AppMode)]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Ist AppMode in OsAlarmAppModeRef?</p>\n<p class=\"fig-p\">├── JA ──► Initialisiere Alarm (ABSOLUTE / RELATIVE mit AlarmTime, CycleTime)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm verbleibt inaktiv (Aktivierung zur Laufzeit via SetRelAlarm / SetAbsAlarm)</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">[Counter Tick / IncrementCounter]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">Counter-Stand == Verfallszeitpunkt?</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├── NEIN ─► Weiterer Zählerbetrieb</p>\n<p class=\"fig-p\">└── JA ───► Triggere deterministische OsAlarmAction (Synchron im ISR- bzw. Counter-Kontext):</p>\n<p class=\"fig-p\">├── ActivateTask:       ActivateTask(TaskID)</p>\n<p class=\"fig-p\">├── SetEvent:           SetEvent(TaskID, EventMask)</p>\n<p class=\"fig-p\">├── Callback:           Aufruf von OsAlarmCallbackName()</p>\n<p class=\"fig-p\">├── IncrementCounter:   Inkrementiere Ziel-Counter</p>\n<p class=\"fig-p\">└── BudgetReplenish:    Auffüllen des Execution Budgets (Timing Protection)</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">OsAlarmCycleTime > 0?</p>\n<p class=\"fig-p\">├── JA ──► Berechne nächsten Verfallspunkt (Alarm bleibt scharf)</p>\n<p class=\"fig-p\">└── NEIN ─► Alarm geht in Status 'CANCELLED/STOPPED'</p>\n<ul class=\"fig-list\">\n<li><strong>Trigger:</strong> Expiration tritt ein, wenn der referenzierte Basiszähler den Zielwert erreicht.</li>\n<li><strong>Synchronizität:</strong> Die konfigurierte Aktion wird synchron innerhalb des Kontexts ausgeführt, der den zugrundeliegenden Zähler fortschreibt (z. B. Timer-ISR bei HW-Countern oder Task-Kontext bei SW-Countern via <code>IncrementCounter()</code>).</li>\n<li><strong>Reload-Verhalten:</strong> Bei <code>OsAlarmCycleTime &gt; 0</code> erfolgt das automatische Nachladen ohne Interaktion des Anwendungs-Codes.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Code-Generierung (Generator-Vertrag):</strong></li>\n<li>Der BSW-OS-Generator übersetzt die Strukturen direkt in ROM-Konstantentabellen (<code>AlarmAutostartType</code>, <code>AlarmType</code>, Deskriptoren) und Funktionszeiger-Arrays.</li>\n<li>Fehlkonfigurationen (z. B. mehrere Choices unter <code>OsAlarmAction</code> oder fehlende <code>OsAlarmCounterRef</code>) müssen vom Generator zur Validierungszeit (Pre-Compile) abgefangen werden.</li>\n<li><strong>Restriktionen & Skalierbarkeitsklassen:</strong></li>\n<li><strong><code>OsAlarmCallback</code>:</strong> In sicherheitskritischen Systemen bzw. höheren Scalability Classes (SC3/SC4 mit Memory-Protection / Timing-Protection) ist die Verwendung von Callbacks oft restriktiert oder verboten, da sie im Interrupt-Kontext laufen und Stack-Overhead sowie Schutzbereichsverletzungen begünstigen. Bevorzugt sind <code>OsAlarmActivateTask</code> oder <code>OsAlarmSetEvent</code>.</li>\n<li><strong>Extended vs. Basic Tasks:</strong> <code>OsAlarmSetEvent</code> darf normativ nur auf Tasks referenzieren, die als Extended Tasks konfiguriert sind (Besitz mindestens eines <code>OsEvent</code>).</li>\n<li><strong>Multi-Core & Partitioning (Memory Protection):</strong></li>\n<li><code>OsAlarmAccessingApplication</code> bestimmt die Berechtigungsmatrix in OS-Applications (<code>Trusted</code> vs. <code>Non-Trusted</code>). Fehlt einer aufrufenden Partition die Referenz in <code>OsAlarmAccessingApplication</code>, retournieren die APIs <code>SetRelAlarm()</code>, <code>SetAbsAlarm()</code> und <code>CancelAlarm()</code> den Statuscode <code>E_OS_ACCESS</code>.</li>\n<li>Alarme laufen zwingend auf dem Core, dem der referenzierte Basiszähler (<code>OsAlarmCounterRef</code>) zugewiesen ist. Cross-Core-Alarmaktionen erfordern Core-übergreifende Inter-OS-Kommunikation (IOC) oder Rescheduling durch den OS-Kernel.</li>\n</ul>"}], "trans": [{"from": "FIG-2d9ec7a49c4ee5b6", "to": "FIG-2a26d9c0e1cd7af6", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>OsAlarmCallback:</strong> Ergänzung der optionalen Fremdreferenz <code>OsMemoryMappingCodeLocationRef</code> (<code>EcucForeignReferenceDef</code>, Multiplizität <code>[0..1]</code>) mit Zieltyp <code>SW-ADDR-METHOD</code>.</li>\n</ul>"}, {"from": "FIG-2a26d9c0e1cd7af6", "to": "FIG-2791e9a190bcaa26", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Layout:</strong> Neuanordnung des Diagramms; die Zielcontainer <code>OsCounter</code>, <code>OsTask</code> und <code>OsEvent</code> werden nun als vollständige Container (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..*]</code>) innerhalb der Diagrammgrenzen dargestellt.</li>\n<li><strong>OsAlarmAction:</strong> Umordnung der Choice-Elemente (<code>OsAlarmIncrementCounter</code> steht nun an oberster Position).</li>\n<li><strong>OsAlarmAutostart:</strong> <code>OsAlarmAppModeRef</code> wurde an die oberste Position innerhalb des Containers verschoben.</li>\n</ul>"}, {"from": "FIG-2791e9a190bcaa26", "to": "FIG-4da60f542df9ab87", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4da60f542df9ab87", "to": "FIG-d17ad99c3d408f84", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>OsAlarmAction:</strong> Ergänzung des neuen Choice-Zweigs <code>OsAlarmBudgetReplenish</code> (<code>EcucParamConfContainerDef</code>, Multiplizität <code>[0..1]</code>) mit der obligatorischen Referenz <code>OsAlarmBudgetReplenishRef</code> (<code>EcucReferenceDef</code>, Multiplizität <code>[1..1]</code>).</li>\n</ul>"}]};
